#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<long long> maximumCoins(vector<int>& heroes, vector<int>& monsters, vector<int>& coins) {
        int n=monsters.size();
        vector<pair<int,int>> a;
        for(int i=0;i<n;++i)a.push_back({monsters[i],coins[i]});
        sort(a.begin(),a.end());
        vector<long long> pref(n+1);
        vector<int> powers;
        for(int i=0;i<n;++i) {powers.push_back(a[i].first);pref[i+1]=pref[i]+a[i].second;}
        vector<long long> ans;
        for(int h:heroes) {
            int count=upper_bound(powers.begin(),powers.end(),h)-powers.begin();
            ans.push_back(pref[count]);
        }
        return ans;
    }
};
